const request = require('request');

const options = {
  method: 'POST',
  url: 'https://api.procore.com/rest/v1.0/projects/%7Bproject_id%7D/submittal_responses',
  headers: {'content-type': 'application/json'},
  body: {submittal_response: {name: 'Approved', considered: 'approved'}},
  json: true
};

request(options, function (error, response, body) {
  if (error) throw new Error(error);

  console.log(body);
});

var client = new HttpClient();
var request = new HttpRequestMessage
{
    Method = HttpMethod.Post,
    RequestUri = new Uri("https://api.procore.com/rest/v1.0/projects/%7Bproject_id%7D/submittal_responses"),
    Content = new StringContent("{\"submittal_response\":{\"name\":\"Approved\",\"considered\":\"approved\"}}")
    {
        Headers =
        {
            ContentType = new MediaTypeHeaderValue("application/json")
        }
    }
};
using (var response = await client.SendAsync(request))
{
    response.EnsureSuccessStatusCode();
    var body = await response.Content.ReadAsStringAsync();
    Console.WriteLine(body);
}
